/**
 * Central registry of application error codes.
 *
 * Isomorphic: safe to import from both server and client code (no runtime deps).
 */
export const API_ERROR_CODES = {
  BAD_REQUEST: {
    status: 400,
    message: "The request could not be processed.",
    retryable: false,
  },
  UNAUTHORIZED: {
    status: 401,
    message: "You must be signed in to perform this action.",
    retryable: false,
  },
  FORBIDDEN: {
    status: 403,
    message: "You do not have permission to perform this action.",
    retryable: false,
  },
  NOT_FOUND: {
    status: 404,
    message: "The requested resource was not found.",
    retryable: false,
  },
  CONFLICT: {
    status: 409,
    message: "The request conflicts with the current state of the resource.",
    retryable: false,
  },
  VALIDATION_ERROR: {
    status: 422,
    message: "Please correct the highlighted fields.",
    retryable: false,
  },
  RATE_LIMITED: {
    status: 429,
    message: "Too many requests. Please try again shortly.",
    retryable: true,
  },
  INTERNAL_ERROR: {
    status: 500,
    message: "Something went wrong. Please try again.",
    retryable: true,
  },
  DATABASE_ERROR: {
    status: 500,
    message: "Something went wrong. Please try again.",
    retryable: true,
  },
  UPSTREAM_ERROR: {
    status: 502,
    message: "A dependent service failed. Please try again.",
    retryable: true,
  },
  SERVICE_UNAVAILABLE: {
    status: 503,
    message: "The service is temporarily unavailable. Please try again.",
    retryable: true,
  },
} as const satisfies Record<
  string,
  { status: number; message: string; retryable: boolean }
>

export type ApiErrorCode = keyof typeof API_ERROR_CODES

export function isApiErrorCode(value: unknown): value is ApiErrorCode {
  return typeof value === "string" && Object.hasOwn(API_ERROR_CODES, value)
}

export function getErrorStatus(code: ApiErrorCode): number {
  return API_ERROR_CODES[code].status
}

import { API_ERROR_CODES, type ApiErrorCode } from "@/lib/api/api-error-codes"

/** Field-level validation details: `{ "email": ["Enter a valid email address."] }`. */
export type ApiErrorDetails = Record<string, string[]>

type ApiErrorOptions = {
  /**
   * Message shown to the client. Must be safe to expose; defaults to the
   * registry message for the code. Never pass raw exception messages here.
   */
  message?: string
  details?: ApiErrorDetails
  /** Original error, kept for server-side logging only. */
  cause?: unknown
  /** Extra context for server logs only. Never sent to clients. */
  logContext?: Record<string, unknown>
}

/**
 * Typed application error for expected failures.
 * Services throw these; the API handler converts them into the response envelope.
 */
export class ApiError extends Error {
  readonly code: ApiErrorCode
  readonly status: number
  readonly publicMessage: string
  readonly details?: ApiErrorDetails
  readonly logContext?: Record<string, unknown>

  constructor(code: ApiErrorCode, options: ApiErrorOptions = {}) {
    const publicMessage = options.message ?? API_ERROR_CODES[code].message
    super(publicMessage, { cause: options.cause })
    this.name = "ApiError"
    this.code = code
    this.status = API_ERROR_CODES[code].status
    this.publicMessage = publicMessage
    this.details = options.details
    this.logContext = options.logContext
  }

  get isServerError(): boolean {
    return this.status >= 500
  }
}

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError
}

import { NextResponse } from "next/server"

import type { ApiErrorCode } from "@/lib/api/api-error-codes"
import type { ApiError, ApiErrorDetails } from "@/lib/api/api-error"

/*
 * The single API response contract. Types here are shared with the client
 * (import them with `import type` from client code); the builders are server-side.
 */

export const REQUEST_ID_HEADER = "x-request-id"

export type ApiMeta = {
  requestId: string
}

export type ApiSuccessBody<T> = {
  success: true
  data: T
  meta: ApiMeta
}

export type ApiErrorBody = {
  success: false
  error: {
    code: ApiErrorCode
    message: string
    details?: ApiErrorDetails
  }
  meta: ApiMeta
}

export type ApiResponseBody<T> = ApiSuccessBody<T> | ApiErrorBody

type ResponseInit = {
  status?: number
  headers?: HeadersInit
}

export function successResponse<T>(
  data: T,
  requestId: string,
  init: ResponseInit = {}
): NextResponse<ApiSuccessBody<T>> {
  const headers = new Headers(init.headers)
  headers.set(REQUEST_ID_HEADER, requestId)

  return NextResponse.json(
    { success: true, data, meta: { requestId } },
    { status: init.status ?? 200, headers }
  )
}

export function errorResponse(
  error: ApiError,
  requestId: string
): NextResponse<ApiErrorBody> {
  const body: ApiErrorBody = {
    success: false,
    error: {
      code: error.code,
      message: error.publicMessage,
      ...(error.details ? { details: error.details } : {}),
    },
    meta: { requestId },
  }

  return NextResponse.json(body, {
    status: error.status,
    headers: { [REQUEST_ID_HEADER]: requestId },
  })
}

import "server-only"

import { z } from "zod"

const LOG_LEVELS = ["fatal", "error", "warn", "info", "debug", "trace", "silent"] as const

const serverEnvSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  LOG_LEVEL: z.enum(LOG_LEVELS).optional(),
  DATABASE_URL: z.url({ protocol: /^postgres(ql)?$/ }),
  CLERK_SECRET_KEY: z.string().min(1),
  CLERK_WEBHOOK_SIGNING_SECRET: z.string().min(1).optional(),
})

export type ServerEnv = z.infer<typeof serverEnvSchema>

let cached: ServerEnv | undefined

/**
 * Validated server environment. Validation is lazy so `next build` and tests
 * do not require secrets; the first runtime access fails fast if misconfigured.
 * Error output lists variable names only, never their values.
 */
export function getServerEnv(): ServerEnv {
  if (cached) return cached

  const result = serverEnvSchema.safeParse(process.env)
  if (!result.success) {
    const invalid = result.error.issues.map((issue) => issue.path.join("."))
    throw new Error(
      `Invalid or missing server environment variables: ${[...new Set(invalid)].join(", ")}`
    )
  }

  cached = result.data
  return cached
}

/** Log level resolution does not require the full env to be valid. */
export function getLogLevel(): (typeof LOG_LEVELS)[number] {
  const parsed = z.enum(LOG_LEVELS).safeParse(process.env.LOG_LEVEL)
  if (parsed.success) return parsed.data
  if (process.env.NODE_ENV === "test") return "silent"
  return process.env.NODE_ENV === "production" ? "info" : "debug"
}

import "server-only"

import { AsyncLocalStorage } from "node:async_hooks"
import { randomUUID } from "node:crypto"

import type { Logger } from "pino"

import { logger } from "@/lib/logger/logger"

export type RequestContext = {
  requestId: string
  method: string
  route: string
  logger: Logger
}

const storage = new AsyncLocalStorage<RequestContext>()

const REQUEST_ID_PATTERN = /^req_[A-Za-z0-9_-]{8,64}$/

export function generateRequestId(): string {
  return `req_${randomUUID().replaceAll("-", "")}`
}

/**
 * Reuses the request ID assigned by the proxy when it is well-formed,
 * otherwise generates a new one. Arbitrary client values are never trusted.
 */
export function resolveRequestId(headers: Headers): string {
  const incoming = headers.get("x-request-id")
  return incoming && REQUEST_ID_PATTERN.test(incoming) ? incoming : generateRequestId()
}

export function runWithRequestContext<T>(
  context: Omit<RequestContext, "logger">,
  fn: () => T
): T {
  const child = logger.child({
    requestId: context.requestId,
    method: context.method,
    route: context.route,
  })
  return storage.run({ ...context, logger: child }, fn)
}

export function getRequestContext(): RequestContext | undefined {
  return storage.getStore()
}

/** Logger bound to the current request (falls back to the root logger). */
export function getLogger(): Logger {
  return storage.getStore()?.logger ?? logger
}

import { REQUEST_ID_HEADER } from "@/lib/api/api-response"

/*
 * Dependency-free so it can be shared by the proxy and route handlers.
 * Uses the Web Crypto global (available in Node.js and the proxy runtime).
 */

const REQUEST_ID_PATTERN = /^req_[A-Za-z0-9_-]{8,64}$/

export function generateRequestId(): string {
  return `req_${crypto.randomUUID().replaceAll("-", "")}`
}

export function isValidRequestId(value: string | null | undefined): value is string {
  return typeof value === "string" && REQUEST_ID_PATTERN.test(value)
}

/**
 * Reuses the request ID assigned by the proxy when it is well-formed,
 * otherwise generates a new one.
 */
export function resolveRequestId(headers: Headers): string {
  const incoming = headers.get(REQUEST_ID_HEADER)
  return isValidRequestId(incoming) ? incoming : generateRequestId()
}

import "server-only"

import { AsyncLocalStorage } from "node:async_hooks"

import type { Logger } from "pino"

import { logger } from "@/lib/logger/logger"

export type RequestContext = {
  requestId: string
  method: string
  route: string
  logger: Logger
}

const storage = new AsyncLocalStorage<RequestContext>()

/**
 * Runs `fn` with a request-scoped context so services and repositories can log
 * with the same request ID without threading it through every call.
 */
export function runWithRequestContext<T>(
  context: Omit<RequestContext, "logger">,
  fn: () => T
): T {
  const child = logger.child({
    requestId: context.requestId,
    method: context.method,
    route: context.route,
  })
  return storage.run({ ...context, logger: child }, fn)
}

export function getRequestContext(): RequestContext | undefined {
  return storage.getStore()
}

/** Logger bound to the current request (falls back to the root logger). */
export function getLogger(): Logger {
  return storage.getStore()?.logger ?? logger
}

import { ApiError } from "@/lib/api/api-error"

/*
 * Maps Prisma errors to safe application errors. Detection is structural
 * (error name + code) so it works for any generated client instance and in
 * tests without constructing real Prisma errors. Raw Prisma messages, SQL and
 * metadata are kept only as `cause` for server logs.
 */

type PrismaLikeError = Error & { code?: string; meta?: unknown }

const CONNECTION_ERROR_CODES = new Set([
  "P1000", // authentication failed
  "P1001", // can't reach database server
  "P1002", // database server timed out
  "P1008", // operations timed out
  "P1017", // server closed the connection
  "P2024", // connection pool timeout
])

function isPrismaKnownRequestError(error: unknown): error is PrismaLikeError {
  return (
    error instanceof Error &&
    error.name === "PrismaClientKnownRequestError" &&
    typeof (error as PrismaLikeError).code === "string"
  )
}

export function isPrismaError(error: unknown): error is Error {
  return error instanceof Error && error.name.startsWith("PrismaClient")
}

export function isUniqueConstraintError(error: unknown): boolean {
  return isPrismaKnownRequestError(error) && error.code === "P2002"
}

export function isRecordNotFoundError(error: unknown): boolean {
  return isPrismaKnownRequestError(error) && error.code === "P2025"
}

export function mapPrismaError(error: unknown): ApiError | undefined {
  if (!isPrismaError(error)) return undefined

  if (isPrismaKnownRequestError(error)) {
    const code = error.code as string
    if (code === "P2002") return new ApiError("CONFLICT", { cause: error, logContext: { prismaCode: code } })
    if (code === "P2025") return new ApiError("NOT_FOUND", { cause: error, logContext: { prismaCode: code } })
    if (CONNECTION_ERROR_CODES.has(code)) {
      return new ApiError("SERVICE_UNAVAILABLE", { cause: error, logContext: { prismaCode: code } })
    }
    return new ApiError("DATABASE_ERROR", { cause: error, logContext: { prismaCode: code } })
  }

  if (error.name === "PrismaClientInitializationError") {
    return new ApiError("SERVICE_UNAVAILABLE", { cause: error })
  }

  // PrismaClientValidationError, PrismaClientRustPanicError, unknown request errors.
  return new ApiError("DATABASE_ERROR", { cause: error })
}

import "server-only"

import { z } from "zod"

import { ApiError, isApiError, type ApiErrorDetails } from "@/lib/api/api-error"
import { mapPrismaError } from "@/lib/db/prisma-errors"

/** Converts Zod issues into `{ "field.path": ["message"] }`. */
export function zodErrorToDetails(error: z.ZodError): ApiErrorDetails {
  const details: ApiErrorDetails = {}
  for (const issue of error.issues) {
    const key = issue.path.length > 0 ? issue.path.join(".") : "_root"
    ;(details[key] ??= []).push(issue.message)
  }
  return details
}

/**
 * Normalizes any thrown value into an ApiError with a client-safe message.
 * Unknown errors become INTERNAL_ERROR; their message is never exposed.
 */
export function toApiError(error: unknown): ApiError {
  if (isApiError(error)) return error

  if (error instanceof z.ZodError) {
    return new ApiError("VALIDATION_ERROR", {
      details: zodErrorToDetails(error),
      cause: error,
    })
  }

  const prismaError = mapPrismaError(error)
  if (prismaError) return prismaError

  return new ApiError("INTERNAL_ERROR", { cause: error })
}

import "server-only"

import type { NextRequest } from "next/server"
import type { Logger } from "pino"

import type { ApiErrorCode } from "@/lib/api/api-error-codes"
import { toApiError } from "@/lib/api/error-handler"
import { errorResponse, successResponse } from "@/lib/api/api-response"
import { resolveRequestId } from "@/lib/api/request-id"
import { getLogger, runWithRequestContext } from "@/lib/logger/request-context"

type RouteParams = Record<string, string | string[] | undefined>

export type ApiHandlerArgs<P extends RouteParams> = {
  request: NextRequest
  params: P
  requestId: string
  logger: Logger
}

export type ApiHandlerResult<T> = {
  data: T
  status?: number
  headers?: HeadersInit
}

type ApiHandlerOptions = {
  /** Route pattern used in logs, e.g. "/api/accounts/[id]". Avoids logging raw IDs. */
  route?: string
}

/** Expected rejections that deserve operator attention; others log at info. */
const WARN_CODES = new Set<ApiErrorCode>(["FORBIDDEN", "CONFLICT", "RATE_LIMITED"])

/**
 * Wraps a route handler with request IDs, request-scoped logging, timing and
 * the standard response envelope. Handlers return data or throw; they never
 * build error responses themselves.
 */
export function createApiHandler<T, P extends RouteParams = RouteParams>(
  handler: (args: ApiHandlerArgs<P>) => Promise<ApiHandlerResult<T>>,
  options: ApiHandlerOptions = {}
) {
  return async function routeHandler(
    request: NextRequest,
    context: { params: Promise<P> }
  ): Promise<Response> {
    const requestId = resolveRequestId(request.headers)
    const method = request.method
    const route = options.route ?? request.nextUrl.pathname
    const startedAt = performance.now()

    return runWithRequestContext({ requestId, method, route }, async () => {
      const log = getLogger()
      const durationMs = () => Math.round(performance.now() - startedAt)

      try {
        const params = (await context?.params) ?? ({} as P)
        const result = await handler({ request, params, requestId, logger: log })
        const response = successResponse(result.data, requestId, {
          status: result.status,
          headers: result.headers,
        })
        log.info({ status: response.status, durationMs: durationMs() }, "request completed")
        return response
      } catch (thrown) {
        const apiError = toApiError(thrown)
        const fields = {
          status: apiError.status,
          errorCode: apiError.code,
          durationMs: durationMs(),
          ...apiError.logContext,
        }

        if (apiError.isServerError) {
          // Single log entry for the failure, including name and stack of the root cause.
          log.error({ ...fields, err: apiError.cause ?? thrown }, "request failed")
        } else if (WARN_CODES.has(apiError.code)) {
          log.warn(fields, "request rejected")
        } else {
          log.info(fields, "request rejected")
        }

        return errorResponse(apiError, requestId)
      }
    })
  }
}

import "server-only"

import type { NextRequest } from "next/server"
import type { z } from "zod"

import { ApiError } from "@/lib/api/api-error"

/*
 * Request parsing helpers. Zod failures are thrown as-is and converted to
 * VALIDATION_ERROR (422) with field details by the API handler.
 */

export async function parseJsonBody<S extends z.ZodType>(
  request: Request,
  schema: S
): Promise<z.infer<S>> {
  const contentType = request.headers.get("content-type") ?? ""
  if (!contentType.toLowerCase().includes("application/json")) {
    throw new ApiError("BAD_REQUEST", { message: "Request body must be JSON." })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch (error) {
    throw new ApiError("BAD_REQUEST", { message: "Request body contains malformed JSON.", cause: error })
  }

  return schema.parse(body)
}

export function parseSearchParams<S extends z.ZodType>(
  request: NextRequest,
  schema: S
): z.infer<S> {
  return schema.parse(Object.fromEntries(request.nextUrl.searchParams))
}

export function parseParams<S extends z.ZodType>(params: unknown, schema: S): z.infer<S> {
  return schema.parse(params)
}

// Prisma schema. Connection URL lives in prisma.config.ts (Prisma 7).
// Migrations are NOT applied automatically; run `pnpm db:migrate` yourself.

generator client {
  provider = "prisma-client"
  output   = "../generated/prisma"
}

datasource db {
  provider = "postgresql"
}

enum UserRole {
  USER
  ADMIN
}

/// Application user. Clerk is the source of truth for identity; this row holds
/// the internal ID used by foreign keys plus application-managed data.
model User {
  /// Internal ID. Other tables reference this, never `clerkId`.
  id             String    @id @default(uuid(7)) @db.Uuid
  /// Clerk user ID (`user_...`). Unique so concurrent syncs cannot duplicate.
  clerkId        String    @unique @map("clerk_id")

  // ---- Synced from Clerk (overwritten on every sync) ----
  /// Primary verified email, or null when Clerk has none verified.
  email          String?
  firstName      String?   @map("first_name")
  lastName       String?   @map("last_name")
  imageUrl       String?   @map("image_url")
  /// Clerk's `updated_at`; used to ignore out-of-order webhook deliveries.
  clerkUpdatedAt DateTime? @map("clerk_updated_at")

  // ---- Application-managed (never touched by Clerk sync) ----
  role           UserRole  @default(USER)
  /// ISO 4217 currency code for reporting.
  baseCurrency   String    @default("USD") @map("base_currency") @db.Char(3)

  /// Soft-delete marker set when Clerk reports `user.deleted`.
  deletedAt      DateTime? @map("deleted_at")
  createdAt      DateTime  @default(now()) @map("created_at")
  updatedAt      DateTime  @updatedAt @map("updated_at")

  @@index([email])
  @@map("users")
}

import { config } from "dotenv"
import { defineConfig } from "prisma/config"

// Next.js reads .env.local before .env; mirror that for the Prisma CLI.
config({ path: [".env.local", ".env"], quiet: true })

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env.DATABASE_URL,
  },
})

import "server-only"

import { PrismaPg } from "@prisma/adapter-pg"

import { PrismaClient } from "@/generated/prisma/client"
import { getServerEnv } from "@/lib/config/env"

function createPrismaClient(): PrismaClient {
  const adapter = new PrismaPg({ connectionString: getServerEnv().DATABASE_URL })
  return new PrismaClient({ adapter })
}

const globalForPrisma = globalThis as unknown as { __prisma?: PrismaClient }

/**
 * Lazily created singleton. Reused across HMR reloads in development so the
 * connection pool is not exhausted. Only repositories should import this.
 */
export function getPrisma(): PrismaClient {
  if (!globalForPrisma.__prisma) {
    globalForPrisma.__prisma = createPrismaClient()
  }
  return globalForPrisma.__prisma
}

export type { PrismaClient }

import "server-only"

import type { User } from "@/generated/prisma/client"
import { getPrisma } from "@/lib/db/prisma"
import { isUniqueConstraintError } from "@/lib/db/prisma-errors"
import type { ClerkUserProfile } from "@/schemas/user.schema"

export type { User }

/** Fields Clerk sync may write. Application-managed fields are excluded by construction. */
function toSyncedFields(profile: ClerkUserProfile) {
  return {
    email: profile.email,
    firstName: profile.firstName,
    lastName: profile.lastName,
    imageUrl: profile.imageUrl,
    clerkUpdatedAt: profile.clerkUpdatedAt,
  }
}

export const usersRepository = {
  findByClerkId(clerkId: string): Promise<User | null> {
    return getPrisma().user.findUnique({ where: { clerkId } })
  },

  findById(id: string): Promise<User | null> {
    return getPrisma().user.findUnique({ where: { id } })
  },

  /**
   * Idempotent upsert keyed by the unique `clerkId`. On update only
   * Clerk-synced fields are written. If two requests race to create the same
   * user, the loser hits the unique constraint and re-reads the winner's row.
   */
  async upsertFromClerk(profile: ClerkUserProfile): Promise<User> {
    const synced = toSyncedFields(profile)
    try {
      return await getPrisma().user.upsert({
        where: { clerkId: profile.clerkId },
        create: { clerkId: profile.clerkId, ...synced },
        update: synced,
      })
    } catch (error) {
      if (!isUniqueConstraintError(error)) throw error
      const existing = await getPrisma().user.findUnique({ where: { clerkId: profile.clerkId } })
      if (!existing) throw error
      return existing
    }
  },

  /**
   * Soft delete: keeps the row (and every foreign key pointing at it) but
   * clears synced personal data. Application data is retained.
   */
