import "server-only"

import type { UserJSON, WebhookEvent } from "@clerk/nextjs/server"

import { fetchClerkUser } from "@/clients/clerk/clerk-users.client"
import type { ClerkUserSource } from "@/clients/clerk/types"
import { ApiError } from "@/lib/api/api-error"
import { getLogger } from "@/lib/logger/request-context"
import { usersRepository, type User } from "@/repositories/users.repository"
import type { ClerkUserProfile, UpdateCurrentUserInput, UserDto } from "@/schemas/user.schema"

export type SyncOutcome =
  | "upserted"
  | "skipped_stale"
  | "skipped_deleted"
  | "deleted"
  | "already_deleted"
  | "ignored"

// ---------------------------------------------------------------------------
// Mapping
// ---------------------------------------------------------------------------

export function fromWebhookUser(json: UserJSON): ClerkUserSource {
  return {
    id: json.id,
    primaryEmailAddressId: json.primary_email_address_id,
    emailAddresses: (json.email_addresses ?? []).map((address) => ({
      id: address.id,
      emailAddress: address.email_address,
      verified: address.verification?.status === "verified",
    })),
    firstName: json.first_name,
    lastName: json.last_name,
    imageUrl: json.image_url || null,
    updatedAt: json.updated_at,
  }
}

/**
 * Picks the primary email only if verified, otherwise the first verified
 * email, otherwise null. Unverified addresses are never stored.
 */
export function selectVerifiedEmail(source: ClerkUserSource): string | null {
  const verified = source.emailAddresses.filter((address) => address.verified)
  const primary = verified.find((address) => address.id === source.primaryEmailAddressId)
  return (primary ?? verified[0])?.emailAddress.toLowerCase() ?? null
}

export function toClerkUserProfile(source: ClerkUserSource): ClerkUserProfile {
  return {
    clerkId: source.id,
    email: selectVerifiedEmail(source),
    firstName: source.firstName?.trim() || null,
    lastName: source.lastName?.trim() || null,
    imageUrl: source.imageUrl || null,
    clerkUpdatedAt: new Date(source.updatedAt),
  }
}

export function toUserDto(user: User): UserDto {
  return {
    id: user.id,
    email: user.email,
    firstName: user.firstName,
    lastName: user.lastName,
    imageUrl: user.imageUrl,
    role: user.role,
    baseCurrency: user.baseCurrency,
    createdAt: user.createdAt.toISOString(),
  }
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export const usersService = {
  /**
   * Idempotent Clerk -> database sync. Safe under at-least-once delivery:
   * repeated events produce the same row, older events never overwrite newer
   * data, and deleted users are never resurrected.
   */
  async syncFromClerk(source: ClerkUserSource): Promise<{ outcome: SyncOutcome; user?: User }> {
    const profile = toClerkUserProfile(source)
    const existing = await usersRepository.findByClerkId(profile.clerkId)

    if (existing?.deletedAt) {
      return { outcome: "skipped_deleted" }
    }
    if (existing?.clerkUpdatedAt && existing.clerkUpdatedAt > profile.clerkUpdatedAt) {
      return { outcome: "skipped_stale", user: existing }
    }

    const user = await usersRepository.upsertFromClerk(profile)
    return { outcome: "upserted", user }
  },

  async markDeleted(clerkId: string): Promise<SyncOutcome> {
    const existing = await usersRepository.findByClerkId(clerkId)
    if (existing?.deletedAt) return "already_deleted"
    await usersRepository.markDeletedByClerkId(clerkId, new Date())
    return "deleted"
  },

  /** Dispatches a verified Clerk webhook event. Unknown types are acknowledged and ignored. */
  async handleClerkWebhookEvent(event: WebhookEvent): Promise<SyncOutcome> {
    switch (event.type) {
      case "user.created":
      case "user.updated":
        return (await usersService.syncFromClerk(fromWebhookUser(event.data))).outcome
      case "user.deleted": {
        const clerkId = event.data.id
        if (!clerkId) {
          throw new ApiError("BAD_REQUEST", { message: "Webhook payload is missing the user ID." })
        }
        return usersService.markDeleted(clerkId)
      }
      default:
        return "ignored"
    }
  },

  /**
   * Resolves the internal user for a verified Clerk ID. Normal path is a
   * single local lookup; the Clerk API is called only when the webhook has
   * not yet created the row.
   */
  async resolveAuthenticatedUser(clerkId: string): Promise<User> {
    const existing = await usersRepository.findByClerkId(clerkId)
    if (existing) {
      if (existing.deletedAt) throw new ApiError("FORBIDDEN", { message: "This account has been deactivated." })
      return existing
    }

    getLogger().info({ event: "user.sync.fallback" }, "local user missing; syncing from Clerk")
    const source = await fetchClerkUser(clerkId)
    if (!source) throw new ApiError("UNAUTHORIZED")

    const { user } = await usersService.syncFromClerk(source)
    if (!user) throw new ApiError("FORBIDDEN", { message: "This account has been deactivated." })
    return user
  },

  async updateCurrentUser(user: User, input: UpdateCurrentUserInput): Promise<User> {
    return usersRepository.updateBaseCurrency(user.id, input.baseCurrency)
  },
}

import "server-only"

import { auth } from "@clerk/nextjs/server"

import { ApiError } from "@/lib/api/api-error"
import type { User } from "@/repositories/users.repository"
import type { UserRole } from "@/schemas/user.schema"
import { usersService } from "@/services/users.service"

export type AuthContext = {
  /** Verified Clerk user ID from the session token. */
  clerkUserId: string
  /** Internal application user; use `user.id` for foreign keys. */
  user: User
}

/**
 * Server-side authentication guard for route handlers and server actions.
 * Identity comes only from Clerk's verified session; client-supplied IDs are
 * never trusted. Throws UNAUTHORIZED (401) when there is no valid session.
 */
export async function requireAuth(): Promise<AuthContext> {
  const { userId } = await auth()
  if (!userId) throw new ApiError("UNAUTHORIZED")

  const user = await usersService.resolveAuthenticatedUser(userId)
  return { clerkUserId: userId, user }
}

/** Throws FORBIDDEN (403) unless the user has one of the allowed roles. */
export function requireRole(user: User, ...allowed: UserRole[]): void {
  if (!allowed.includes(user.role)) {
    throw new ApiError("FORBIDDEN", { logContext: { requiredRoles: allowed } })
  }
}

/**
 * Ownership check for user-scoped resources. Responds NOT_FOUND rather than
 * FORBIDDEN so other users' resource IDs cannot be probed.
 */
export function assertOwnership(user: User, resource: { userId: string } | null | undefined): void {
  if (!resource || resource.userId !== user.id) {
    throw new ApiError("NOT_FOUND")
  }
}

import "server-only"

import { getPrisma } from "@/lib/db/prisma"

export const healthRepository = {
  async ping(): Promise<void> {
    await getPrisma().$queryRaw`SELECT 1`
  },

  /** Installed pgvector version, or null when the extension is not enabled. */
  async getVectorExtensionVersion(): Promise<string | null> {
    const rows = await getPrisma().$queryRaw<Array<{ extversion: string }>>`
      SELECT extversion FROM pg_extension WHERE extname = 'vector'
    `
    return rows[0]?.extversion ?? null
  },
}

import "server-only"

import { healthRepository } from "@/repositories/health.repository"

export type HealthStatus = {
  status: "ok"
  database: "ok"
  vectorExtension: boolean
}

export const healthService = {
  /** Throws (mapped to 503 by the API handler) when the database is unreachable. */
  async check(): Promise<HealthStatus> {
    await healthRepository.ping()
    const vectorVersion = await healthRepository.getVectorExtensionVersion()
    return { status: "ok", database: "ok", vectorExtension: vectorVersion !== null }
  },
}

import { verifyWebhook } from "@clerk/nextjs/webhooks"

import { ApiError } from "@/lib/api/api-error"
import { createApiHandler } from "@/lib/api/api-handler"
import { getServerEnv } from "@/lib/config/env"
import { usersService } from "@/services/users.service"

/**
 * Clerk webhook receiver (public route; authenticity comes from the Svix signature).
 *
 * - 2xx: processed or intentionally ignored. Clerk will not retry.
 * - 400: signature or payload invalid. Retrying cannot help.
 * - 5xx: transient failure (e.g. database down). Clerk retries with backoff.
 */
export const POST = createApiHandler(
  async ({ request, logger }) => {
    const eventId = request.headers.get("svix-id") ?? undefined
    const log = logger.child({ webhookEventId: eventId })

    const signingSecret = getServerEnv().CLERK_WEBHOOK_SIGNING_SECRET
    if (!signingSecret) {
      throw new ApiError("SERVICE_UNAVAILABLE", {
        logContext: { reason: "CLERK_WEBHOOK_SIGNING_SECRET is not configured" },
      })
    }

    let event
    try {
      event = await verifyWebhook(request, { signingSecret })
    } catch (error) {
      throw new ApiError("BAD_REQUEST", {
        message: "Invalid webhook signature.",
        cause: error,
        logContext: { webhookEventId: eventId },
      })
    }

    const outcome = await usersService.handleClerkWebhookEvent(event)
    log.info({ webhookType: event.type, outcome }, "clerk webhook processed")

    return { data: { received: true, outcome } }
  },
  { route: "/api/webhooks/clerk" }
)

import { createApiHandler } from "@/lib/api/api-handler"
import { requireAuth } from "@/lib/auth/authorization"
import { parseJsonBody } from "@/lib/validation/request"
import { updateCurrentUserSchema } from "@/schemas/user.schema"
import { toUserDto, usersService } from "@/services/users.service"

/** GET /api/me — the signed-in user's application profile. */
export const GET = createApiHandler(
  async () => {
    const { user } = await requireAuth()
    return { data: toUserDto(user) }
  },
  { route: "/api/me" }
)

/** PATCH /api/me — update application-managed preferences. */
export const PATCH = createApiHandler(
  async ({ request }) => {
    const { user } = await requireAuth()
    const input = await parseJsonBody(request, updateCurrentUserSchema)
    const updated = await usersService.updateCurrentUser(user, input)
    return { data: toUserDto(updated) }
  },
  { route: "/api/me" }
)

import { createApiHandler } from "@/lib/api/api-handler"
import { healthService } from "@/services/health.service"

/** GET /api/health — public liveness + database/pgvector readiness probe. */
export const GET = createApiHandler(
  async () => ({ data: await healthService.check() }),
  { route: "/api/health" }
)

import { NextResponse, type NextRequest } from "next/server"

import { REQUEST_ID_HEADER } from "@/lib/api/api-response"
import { generateRequestId } from "@/lib/api/request-id"

/**
 * Assigns a fresh request ID to every request passing through the proxy.
 * Client-supplied values are overwritten so logs cannot be spoofed. The ID is
 * forwarded to route handlers as a request header and echoed on the response.
 */
export function withRequestId(request: NextRequest): NextResponse {
  const requestId = generateRequestId()
  const headers = new Headers(request.headers)
  headers.set(REQUEST_ID_HEADER, requestId)

  const response = NextResponse.next({ request: { headers } })
  response.headers.set(REQUEST_ID_HEADER, requestId)
  return response
}

import { createRouteMatcher } from "@clerk/nextjs/server"

/**
 * Pages reachable without signing in. Everything else that is a page
 * requires a session and redirects to sign-in.
 */
export const isPublicPage = createRouteMatcher(["/", "/sign-in(.*)", "/sign-up(.*)"])

/**
 * API routes are never redirected by the proxy. Each route handler enforces
 * auth itself (`requireAuth()`) so it can return a JSON 401 instead of an
 * HTML redirect, and public endpoints (health, webhooks) stay reachable.
 */
export const isApiRoute = createRouteMatcher(["/api(.*)", "/trpc(.*)"])

import type { ClerkMiddlewareAuth } from "@clerk/nextjs/server"
import type { NextRequest } from "next/server"

import { isApiRoute, isPublicPage } from "@/middleware/auth.middleware"
import { withRequestId } from "@/middleware/request-id.middleware"

/**
 * Proxy pipeline, run inside `clerkMiddleware` from the root `proxy.ts`.
 * 1. Protect non-public pages (redirect to sign-in when signed out).
 * 2. Attach a request ID for downstream logging and responses.
 */
export async function proxyHandler(auth: ClerkMiddlewareAuth, request: NextRequest) {
  if (!isApiRoute(request) && !isPublicPage(request)) {
    await auth.protect()
  }
  return withRequestId(request)
}

import { clerkMiddleware } from "@clerk/nextjs/server"

import { proxyHandler } from "@/middleware"

// Next.js 16 request interception entry point (replaces middleware.ts).
export default clerkMiddleware(proxyHandler)

export const config = {
  matcher: [
    // Skip Next.js internals and static files, unless found in search params
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/(api|trpc)(.*)",
  ],
}

import { API_ERROR_CODES, isApiErrorCode, type ApiErrorCode } from "@/lib/api/api-error-codes"
import type { ApiErrorDetails } from "@/lib/api/api-error"
import type { ApiResponseBody } from "@/lib/api/api-response"

/*
 * Typed browser client for the internal API. No server-only imports: only
 * types and the isomorphic error-code registry.
 */

export type ApiClientErrorKind =
  /** Server answered with the standard error envelope (or a non-2xx status). */
  | "http"
  /** fetch() rejected: offline, DNS, CORS, connection reset. */
  | "network"
  /** Body was not valid JSON. */
  | "parse"
  /** Body was JSON but not the expected envelope. */
  | "invalid_response"
  /** Request was cancelled via AbortSignal. */
  | "aborted"

export class ApiClientError extends Error {
  readonly kind: ApiClientErrorKind
  readonly status: number | null
  readonly code: ApiErrorCode | null
  readonly requestId: string | null
  readonly details?: ApiErrorDetails

  constructor(init: {
    kind: ApiClientErrorKind
    message: string
    status?: number | null
    code?: ApiErrorCode | null
    requestId?: string | null
    details?: ApiErrorDetails
    cause?: unknown
  }) {
    super(init.message, { cause: init.cause })
    this.name = "ApiClientError"
    this.kind = init.kind
    this.status = init.status ?? null
    this.code = init.code ?? null
    this.requestId = init.requestId ?? null
    this.details = init.details
  }
}

export function isApiClientError(error: unknown): error is ApiClientError {
  return error instanceof ApiClientError
}

const NETWORK_MESSAGE = "Unable to reach the server. Check your connection and try again."
const UNEXPECTED_MESSAGE = "The server returned an unexpected response. Please try again."

type RequestOptions = {
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE"
  body?: unknown
  signal?: AbortSignal
  headers?: HeadersInit
}

function isEnvelope(value: unknown): value is ApiResponseBody<unknown> {
  if (typeof value !== "object" || value === null) return false
  const body = value as Record<string, unknown>
  const meta = body.meta as Record<string, unknown> | undefined
  if (typeof meta?.requestId !== "string") return false
  if (body.success === true) return "data" in body
  if (body.success === false) {
    const error = body.error as Record<string, unknown> | undefined
    return typeof error?.code === "string" && typeof error?.message === "string"
  }
  return false
}

function fallbackCodeForStatus(status: number): ApiErrorCode {
  const match = (Object.keys(API_ERROR_CODES) as ApiErrorCode[]).find(
    (code) => API_ERROR_CODES[code].status === status
  )
  return match ?? (status >= 500 ? "INTERNAL_ERROR" : "BAD_REQUEST")
}

export async function apiRequest<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const headers = new Headers(options.headers)
  headers.set("Accept", "application/json")
  const hasBody = options.body !== undefined
  if (hasBody) headers.set("Content-Type", "application/json")

  let response: Response
  try {
    response = await fetch(path, {
      method: options.method ?? "GET",
      headers,
      body: hasBody ? JSON.stringify(options.body) : undefined,
      signal: options.signal,
      credentials: "same-origin",
    })
  } catch (error) {
    if (options.signal?.aborted || (error as Error)?.name === "AbortError") {
      throw new ApiClientError({ kind: "aborted", message: "Request was cancelled.", cause: error })
    }
    throw new ApiClientError({ kind: "network", message: NETWORK_MESSAGE, cause: error })
  }

  // fetch() resolves for 4xx/5xx, so the status must be checked explicitly.
  const headerRequestId = response.headers.get("x-request-id")

  let body: unknown
  try {
    body = await response.json()
  } catch (error) {
    throw new ApiClientError({
      kind: response.ok ? "parse" : "http",
      message: UNEXPECTED_MESSAGE,
      status: response.status,
      code: response.ok ? null : fallbackCodeForStatus(response.status),
      requestId: headerRequestId,
      cause: error,
    })
  }

  if (!isEnvelope(body)) {
    throw new ApiClientError({
      kind: response.ok ? "invalid_response" : "http",
      message: UNEXPECTED_MESSAGE,
      status: response.status,
      code: response.ok ? null : fallbackCodeForStatus(response.status),
      requestId: headerRequestId,
    })
  }

  if (body.success && response.ok) return body.data as T

  if (!body.success) {
    throw new ApiClientError({
      kind: "http",
      message: body.error.message,
      status: response.status,
      code: isApiErrorCode(body.error.code) ? body.error.code : fallbackCodeForStatus(response.status),
      requestId: body.meta.requestId,
      details: body.error.details,
    })
  }

  // success: true with a non-2xx status is a contract violation.
  throw new ApiClientError({
    kind: "invalid_response",
    message: UNEXPECTED_MESSAGE,
    status: response.status,
    requestId: body.meta.requestId,
  })
}

export const apiClient = {
  get: <T>(path: string, options?: Omit<RequestOptions, "method" | "body">) =>
    apiRequest<T>(path, { ...options, method: "GET" }),
  post: <T>(path: string, body?: unknown, options?: Omit<RequestOptions, "method" | "body">) =>
    apiRequest<T>(path, { ...options, method: "POST", body }),
  put: <T>(path: string, body?: unknown, options?: Omit<RequestOptions, "method" | "body">) =>
    apiRequest<T>(path, { ...options, method: "PUT", body }),
  patch: <T>(path: string, body?: unknown, options?: Omit<RequestOptions, "method" | "body">) =>
    apiRequest<T>(path, { ...options, method: "PATCH", body }),
  delete: <T>(path: string, options?: Omit<RequestOptions, "method" | "body">) =>
    apiRequest<T>(path, { ...options, method: "DELETE" }),
}

/** Safe, user-presentable message for any error thrown by the client or hooks. */
export function getErrorMessage(error: unknown): string {
  if (isApiClientError(error)) return error.message
  return API_ERROR_CODES.INTERNAL_ERROR.message
}

import { QueryClient } from "@tanstack/react-query"

import { API_ERROR_CODES } from "@/lib/api/api-error-codes"
import { isApiClientError } from "@/lib/api/api-client"

export const MAX_QUERY_RETRIES = 2

/**
 * Retry only failures that may succeed on a second attempt:
 * network errors, 408/429, and 5xx/retryable error codes.
 * Ordinary 4xx, malformed responses and cancellations are never retried.
 */
export function shouldRetryQuery(failureCount: number, error: unknown): boolean {
  if (failureCount >= MAX_QUERY_RETRIES) return false
  if (!isApiClientError(error)) return false

  switch (error.kind) {
    case "network":
      return true
    case "aborted":
    case "parse":
    case "invalid_response":
      return false
    case "http": {
      if (error.code) return API_ERROR_CODES[error.code].retryable
      const status = error.status ?? 0
      return status === 408 || status === 429 || status >= 500
    }
  }
}

export function retryDelay(attempt: number): number {
  return Math.min(1000 * 2 ** attempt, 8000)
}

export function createQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 30_000,
        gcTime: 5 * 60_000,
        refetchOnWindowFocus: false,
        retry: shouldRetryQuery,
        retryDelay,
      },
      mutations: {
        retry: false,
      },
    },
  })
}

"use client"

import { useState, type ReactNode } from "react"
import { QueryClientProvider } from "@tanstack/react-query"

import { createQueryClient } from "@/lib/api/query-client"

export function QueryProvider({ children }: { children: ReactNode }) {
  // One client per browser session; never shared between server requests.
  const [queryClient] = useState(createQueryClient)
  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

"use client"

import type { ReactNode } from "react"

import { Toaster } from "@/components/ui/toast"
import { QueryProvider } from "@/providers/query-provider"

/** Client-side providers composed once for the whole app. */
export function AppProviders({ children }: { children: ReactNode }) {
  return (
    <QueryProvider>
      <Toaster>{children}</Toaster>
    </QueryProvider>
  )
}

/**
 * Query key factory. Every feature adds a namespace here so keys stay
 * hierarchical and invalidation can target a whole feature or one entry:
 *
 *   queryClient.invalidateQueries({ queryKey: queryKeys.users.all })
 */
export const queryKeys = {
  users: {
    all: ["users"] as const,
    me: () => [...queryKeys.users.all, "me"] as const,
  },
} as const

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"

import { apiClient, type ApiClientError } from "@/lib/api/api-client"
import { queryKeys } from "@/hooks/api/query-keys"
import type { UpdateCurrentUserInput, UserDto } from "@/schemas/user.schema"

/*
 * Convention: one file per feature resource. Each file exports
 *  - use<Resource>()        queries (pass `signal` through for cancellation)
 *  - use<Verb><Resource>()  mutations that update/invalidate the cache on success
 */

export function useCurrentUser() {
  return useQuery<UserDto, ApiClientError>({
    queryKey: queryKeys.users.me(),
    queryFn: ({ signal }) => apiClient.get<UserDto>("/api/me", { signal }),
  })
}

export function useUpdateCurrentUser() {
  const queryClient = useQueryClient()

  return useMutation<UserDto, ApiClientError, UpdateCurrentUserInput>({
    mutationFn: (input) => apiClient.patch<UserDto>("/api/me", input),
    onSuccess: (user) => {
      queryClient.setQueryData(queryKeys.users.me(), user)
      return queryClient.invalidateQueries({ queryKey: queryKeys.users.all })
    },
  })
}

