import type { UserJSON, WebhookEvent } from "@clerk/nextjs/server"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { fetchClerkUser } from "@/clients/clerk/clerk-users.client"
import { ApiError } from "@/lib/api/api-error"
import { usersRepository } from "@/repositories/users.repository"
import { selectVerifiedEmail, toClerkUserProfile, usersService } from "@/services/users.service"

import { makeUser } from "../helpers"

vi.mock("@/repositories/users.repository", () => ({
  usersRepository: {
    findByClerkId: vi.fn(),
    upsertFromClerk: vi.fn(),
    markDeletedByClerkId: vi.fn(),
    updateBaseCurrency: vi.fn(),
  },
}))
vi.mock("@/clients/clerk/clerk-users.client", () => ({ fetchClerkUser: vi.fn() }))

const repo = vi.mocked(usersRepository)

function userJson(overrides: Partial<UserJSON> = {}): UserJSON {
  return {
    id: "user_123",
    first_name: "Ada",
    last_name: "Lovelace",
    image_url: "https://img.clerk.com/ada.png",
    primary_email_address_id: "idn_1",
    email_addresses: [
      { id: "idn_1", email_address: "Ada@Example.com", verification: { status: "verified" } },
    ],
    updated_at: Date.parse("2026-02-01T00:00:00Z"),
    ...overrides,
  } as unknown as UserJSON
}

function userEvent(type: "user.created" | "user.updated", data = userJson()): WebhookEvent {
  return { type, data, object: "event" } as unknown as WebhookEvent
}

beforeEach(() => {
  repo.findByClerkId.mockResolvedValue(null)
  repo.upsertFromClerk.mockImplementation(async (profile) => makeUser({ ...profile }))
})

describe("Clerk user mapping", () => {
  it("normalizes the verified primary email to lowercase", () => {
    expect(toClerkUserProfile({
      id: "user_1", primaryEmailAddressId: "a", firstName: " Ada ", lastName: null, imageUrl: "", updatedAt: 0,
      emailAddresses: [{ id: "a", emailAddress: "Ada@Example.com", verified: true }],
    })).toMatchObject({ email: "ada@example.com", firstName: "Ada", lastName: null, imageUrl: null })
  })

  it("returns null when the user has no email addresses", () => {
    expect(selectVerifiedEmail({
      id: "u", primaryEmailAddressId: null, emailAddresses: [], firstName: null, lastName: null, imageUrl: null, updatedAt: 0,
    })).toBeNull()
  })

  it("never stores an unverified email; falls back to another verified address", () => {
    const base = { id: "u", firstName: null, lastName: null, imageUrl: null, updatedAt: 0 }
    expect(selectVerifiedEmail({
      ...base, primaryEmailAddressId: "a",
      emailAddresses: [{ id: "a", emailAddress: "unverified@x.io", verified: false }],
    })).toBeNull()
    expect(selectVerifiedEmail({
      ...base, primaryEmailAddressId: "a",
      emailAddresses: [
        { id: "a", emailAddress: "unverified@x.io", verified: false },
        { id: "b", emailAddress: "verified@x.io", verified: true },
      ],
    })).toBe("verified@x.io")
  })
})

describe("usersService.handleClerkWebhookEvent", () => {
  it("upserts on user.created with only Clerk-synced fields", async () => {
    const outcome = await usersService.handleClerkWebhookEvent(userEvent("user.created"))

    expect(outcome).toBe("upserted")
    expect(repo.upsertFromClerk).toHaveBeenCalledWith({
      clerkId: "user_123",
      email: "ada@example.com",
      firstName: "Ada",
      lastName: "Lovelace",
      imageUrl: "https://img.clerk.com/ada.png",
      clerkUpdatedAt: new Date("2026-02-01T00:00:00Z"),
    })
  })

  it("updates without passing application-managed fields (role, baseCurrency)", async () => {
    repo.findByClerkId.mockResolvedValue(
      makeUser({ role: "ADMIN", baseCurrency: "EUR", clerkUpdatedAt: new Date("2026-01-01T00:00:00Z") })
    )

    await usersService.handleClerkWebhookEvent(userEvent("user.updated", userJson({ first_name: "Augusta" })))

    const profile = repo.upsertFromClerk.mock.calls[0][0]
    expect(profile.firstName).toBe("Augusta")
    expect(profile).not.toHaveProperty("role")
    expect(profile).not.toHaveProperty("baseCurrency")
    expect(profile).not.toHaveProperty("deletedAt")
  })

  it("is idempotent under duplicate delivery", async () => {
    const event = userEvent("user.created")
    const first = await usersService.handleClerkWebhookEvent(event)
    repo.findByClerkId.mockResolvedValue(makeUser({ clerkUpdatedAt: new Date("2026-02-01T00:00:00Z") }))
    const second = await usersService.handleClerkWebhookEvent(event)

    expect([first, second]).toEqual(["upserted", "upserted"])
    expect(repo.upsertFromClerk.mock.calls[0][0]).toEqual(repo.upsertFromClerk.mock.calls[1][0])
  })

  it("ignores out-of-order (older) updates", async () => {
    repo.findByClerkId.mockResolvedValue(makeUser({ clerkUpdatedAt: new Date("2026-03-01T00:00:00Z") }))

    const outcome = await usersService.handleClerkWebhookEvent(userEvent("user.updated"))

    expect(outcome).toBe("skipped_stale")
    expect(repo.upsertFromClerk).not.toHaveBeenCalled()
  })

  it("syncs users with no email address", async () => {
    await usersService.handleClerkWebhookEvent(
      userEvent("user.created", userJson({ email_addresses: [], primary_email_address_id: null }))
    )
    expect(repo.upsertFromClerk.mock.calls[0][0].email).toBeNull()
  })

  it("soft-deletes on user.deleted, retaining the row for foreign keys", async () => {
    // A user with related financial data: the row must survive.
    repo.findByClerkId.mockResolvedValue(makeUser())
    repo.markDeletedByClerkId.mockResolvedValue(makeUser({ deletedAt: new Date() }))

    const outcome = await usersService.handleClerkWebhookEvent({
      type: "user.deleted", data: { id: "user_123", deleted: true, object: "user" },
    } as unknown as WebhookEvent)

    expect(outcome).toBe("deleted")
    expect(repo.markDeletedByClerkId).toHaveBeenCalledWith("user_123", expect.any(Date))
    expect(usersRepository).not.toHaveProperty("delete")
  })

  it("treats repeated user.deleted as already handled", async () => {
    repo.findByClerkId.mockResolvedValue(makeUser({ deletedAt: new Date() }))
    const outcome = await usersService.handleClerkWebhookEvent({
      type: "user.deleted", data: { id: "user_123", deleted: true, object: "user" },
    } as unknown as WebhookEvent)

    expect(outcome).toBe("already_deleted")
    expect(repo.markDeletedByClerkId).not.toHaveBeenCalled()
  })

  it("does not resurrect a deleted user on a late user.created", async () => {
    repo.findByClerkId.mockResolvedValue(makeUser({ deletedAt: new Date() }))
    const outcome = await usersService.handleClerkWebhookEvent(userEvent("user.created"))

    expect(outcome).toBe("skipped_deleted")
    expect(repo.upsertFromClerk).not.toHaveBeenCalled()
  })

  it("acknowledges unrelated event types without side effects", async () => {
    const outcome = await usersService.handleClerkWebhookEvent({ type: "session.created", data: {} } as unknown as WebhookEvent)
    expect(outcome).toBe("ignored")
  })
})

describe("usersService.resolveAuthenticatedUser", () => {
  it("returns the local user without calling Clerk", async () => {
    const user = makeUser()
    repo.findByClerkId.mockResolvedValue(user)

    await expect(usersService.resolveAuthenticatedUser("user_123")).resolves.toBe(user)
    expect(fetchClerkUser).not.toHaveBeenCalled()
  })

  it("syncs from Clerk when the local record is missing", async () => {
    vi.mocked(fetchClerkUser).mockResolvedValue({
      id: "user_123", primaryEmailAddressId: null, emailAddresses: [], firstName: "Ada",
      lastName: null, imageUrl: null, updatedAt: Date.now(),
    })

    const user = await usersService.resolveAuthenticatedUser("user_123")

    expect(fetchClerkUser).toHaveBeenCalledWith("user_123")
    expect(repo.upsertFromClerk).toHaveBeenCalledOnce()
    expect(user.clerkId).toBe("user_123")
  })

  it("rejects deactivated users with FORBIDDEN", async () => {
    repo.findByClerkId.mockResolvedValue(makeUser({ deletedAt: new Date() }))
    await expect(usersService.resolveAuthenticatedUser("user_123")).rejects.toMatchObject({ code: "FORBIDDEN" })
  })

  it("rejects with UNAUTHORIZED when Clerk does not know the user", async () => {
    vi.mocked(fetchClerkUser).mockResolvedValue(null)
    await expect(usersService.resolveAuthenticatedUser("user_gone")).rejects.toBeInstanceOf(ApiError)
    await expect(usersService.resolveAuthenticatedUser("user_gone")).rejects.toMatchObject({ code: "UNAUTHORIZED" })
  })
})

import { beforeEach, describe, expect, it, vi } from "vitest"

import { getPrisma } from "@/lib/db/prisma"
import { usersRepository } from "@/repositories/users.repository"

import { makeUser, prismaError } from "../helpers"

const prismaUser = {
  findUnique: vi.fn(),
  upsert: vi.fn(),
  update: vi.fn(),
}
vi.mock("@/lib/db/prisma", () => ({ getPrisma: vi.fn() }))

const profile = {
  clerkId: "user_123",
  email: "ada@example.com",
  firstName: "Ada",
  lastName: null,
  imageUrl: null,
  clerkUpdatedAt: new Date("2026-02-01T00:00:00Z"),
}

beforeEach(() => {
  vi.mocked(getPrisma).mockReturnValue({ user: prismaUser } as never)
})

describe("usersRepository.upsertFromClerk", () => {
  it("upserts keyed by clerkId and writes only synced fields on update", async () => {
    prismaUser.upsert.mockResolvedValue(makeUser())
    await usersRepository.upsertFromClerk(profile)

    const args = prismaUser.upsert.mock.calls[0][0]
    expect(args.where).toEqual({ clerkId: "user_123" })
    expect(Object.keys(args.update).sort()).toEqual(
      ["clerkUpdatedAt", "email", "firstName", "imageUrl", "lastName"]
    )
  })

  it("recovers from a concurrent-create unique violation by re-reading the row", async () => {
    const winner = makeUser()
    prismaUser.upsert.mockRejectedValue(prismaError("P2002"))
    prismaUser.findUnique.mockResolvedValue(winner)

    await expect(usersRepository.upsertFromClerk(profile)).resolves.toBe(winner)
  })

  it("rethrows other database errors for central mapping", async () => {
    const error = prismaError("P1001")
    prismaUser.upsert.mockRejectedValue(error)

    await expect(usersRepository.upsertFromClerk(profile)).rejects.toBe(error)
  })
})

describe("usersRepository.markDeletedByClerkId", () => {
  it("clears personal data and sets deletedAt, creating a tombstone if needed", async () => {
    prismaUser.upsert.mockResolvedValue(makeUser())
    const deletedAt = new Date()
    await usersRepository.markDeletedByClerkId("user_123", deletedAt)

    const args = prismaUser.upsert.mock.calls[0][0]
    expect(args.create).toEqual({ clerkId: "user_123", deletedAt, email: null, firstName: null, lastName: null, imageUrl: null })
    expect(args.update).toMatchObject({ deletedAt, email: null })
  })
})

import { verifyWebhook } from "@clerk/nextjs/webhooks"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { POST } from "@/app/api/webhooks/clerk/route"
import { getServerEnv } from "@/lib/config/env"
import { usersRepository } from "@/repositories/users.repository"

import { makeRequest, makeUser, noParams, prismaError, readBody } from "../helpers"

vi.mock("@clerk/nextjs/webhooks", () => ({ verifyWebhook: vi.fn() }))
vi.mock("@/lib/config/env", () => ({ getServerEnv: vi.fn(), getLogLevel: () => "silent" }))
vi.mock("@/clients/clerk/clerk-users.client", () => ({ fetchClerkUser: vi.fn() }))
vi.mock("@/repositories/users.repository", () => ({
  usersRepository: {
    findByClerkId: vi.fn(),
    upsertFromClerk: vi.fn(),
    markDeletedByClerkId: vi.fn(),
  },
}))

const repo = vi.mocked(usersRepository)

const createdEvent = {
  type: "user.created",
  object: "event",
  data: {
    id: "user_123",
    first_name: "Ada",
    last_name: null,
    image_url: "",
    primary_email_address_id: null,
    email_addresses: [],
    updated_at: Date.now(),
  },
}

function webhookRequest() {
  return makeRequest("/api/webhooks/clerk", {
    method: "POST",
    headers: { "content-type": "application/json", "svix-id": "msg_1", "svix-signature": "v1,sig" },
    body: JSON.stringify(createdEvent),
  })
}

beforeEach(() => {
  vi.mocked(getServerEnv).mockReturnValue({ CLERK_WEBHOOK_SIGNING_SECRET: "whsec_test" } as never)
  vi.mocked(verifyWebhook).mockResolvedValue(createdEvent as never)
  repo.findByClerkId.mockResolvedValue(null)
  repo.upsertFromClerk.mockResolvedValue(makeUser())
})

describe("POST /api/webhooks/clerk", () => {
  it("verifies the signature with the configured secret and upserts the user", async () => {
    const response = await POST(webhookRequest(), noParams)
    const body = await readBody(response)

    expect(response.status).toBe(200)
    expect(body).toMatchObject({ success: true, data: { received: true, outcome: "upserted" } })
    expect(verifyWebhook).toHaveBeenCalledWith(expect.anything(), { signingSecret: "whsec_test" })
  })

  it("returns 2xx for duplicate deliveries", async () => {
    expect((await POST(webhookRequest(), noParams)).status).toBe(200)
    expect((await POST(webhookRequest(), noParams)).status).toBe(200)
  })

  it("rejects invalid signatures with 400 and never touches the database", async () => {
    vi.mocked(verifyWebhook).mockRejectedValue(new Error("No matching signature found"))

    const response = await POST(webhookRequest(), noParams)
    const raw = await response.text()

    expect(response.status).toBe(400)
    expect(JSON.parse(raw).error).toEqual({ code: "BAD_REQUEST", message: "Invalid webhook signature." })
    expect(raw).not.toContain("No matching signature")
    expect(repo.upsertFromClerk).not.toHaveBeenCalled()
  })

  it("returns 503 when the signing secret is not configured", async () => {
    vi.mocked(getServerEnv).mockReturnValue({} as never)
    const response = await POST(webhookRequest(), noParams)
    expect(response.status).toBe(503)
    expect(verifyWebhook).not.toHaveBeenCalled()
  })

  it("returns a retryable 5xx when the database is unavailable", async () => {
    repo.upsertFromClerk.mockRejectedValue(prismaError("P1001"))
    const response = await POST(webhookRequest(), noParams)
    expect(response.status).toBe(503)
  })

  it("returns 500 for unexpected processing failures so Clerk retries", async () => {
    repo.upsertFromClerk.mockRejectedValue(new Error("unexpected"))
    const response = await POST(webhookRequest(), noParams)
    expect(response.status).toBe(500)
  })
})

import { auth } from "@clerk/nextjs/server"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { GET, PATCH } from "@/app/api/me/route"
import { createApiHandler } from "@/lib/api/api-handler"
import { assertOwnership, requireAuth, requireRole } from "@/lib/auth/authorization"
import { usersService } from "@/services/users.service"

import { makeRequest, makeUser, noParams, readBody } from "../helpers"

vi.mock("@clerk/nextjs/server", () => ({ auth: vi.fn() }))
vi.mock("@/services/users.service", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/services/users.service")>()
  return {
    ...actual,
    usersService: { resolveAuthenticatedUser: vi.fn(), updateCurrentUser: vi.fn() },
  }
})

function signedIn(userId: string | null) {
  vi.mocked(auth).mockResolvedValue({ userId } as never)
}

beforeEach(() => {
  vi.mocked(usersService.resolveAuthenticatedUser).mockResolvedValue(makeUser())
})

describe("requireAuth", () => {
  it("returns 401 UNAUTHORIZED when there is no Clerk session", async () => {
    signedIn(null)
    const response = await GET(makeRequest("/api/me"), noParams)
    const body = await readBody(response)

    expect(response.status).toBe(401)
    expect(body).toMatchObject({ success: false, error: { code: "UNAUTHORIZED" } })
    expect(usersService.resolveAuthenticatedUser).not.toHaveBeenCalled()
  })

  it("resolves the internal user from the verified Clerk ID only", async () => {
    signedIn("user_123")
    const result = await requireAuth()

    expect(usersService.resolveAuthenticatedUser).toHaveBeenCalledWith("user_123")
    expect(result.user.id).toBe(makeUser().id)
  })

  it("ignores client-supplied user IDs", async () => {
    signedIn("user_123")
    await GET(makeRequest("/api/me?userId=user_attacker", { headers: { "x-user-id": "user_attacker" } }), noParams)
    expect(usersService.resolveAuthenticatedUser).toHaveBeenCalledWith("user_123")
  })

  it("returns the user DTO without internal fields", async () => {
    signedIn("user_123")
    const body = await readBody<Record<string, unknown>>(await GET(makeRequest("/api/me"), noParams))

    expect(body.success).toBe(true)
    if (!body.success) return
    expect(body.data).toMatchObject({ email: "ada@example.com", baseCurrency: "USD" })
    expect(body.data).not.toHaveProperty("clerkId")
    expect(body.data).not.toHaveProperty("deletedAt")
  })
})

describe("PATCH /api/me", () => {
  it("returns 422 with field details for invalid input", async () => {
    signedIn("user_123")
    const request = makeRequest("/api/me", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ baseCurrency: "dollars" }),
    })
    const body = await readBody(await PATCH(request, noParams))

    expect(body).toMatchObject({
      success: false,
      error: { code: "VALIDATION_ERROR", details: { baseCurrency: [expect.any(String)] } },
    })
  })

  it("rejects unknown fields such as role (no privilege escalation)", async () => {
    signedIn("user_123")
    const request = makeRequest("/api/me", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ baseCurrency: "EUR", role: "ADMIN" }),
    })
    const response = await PATCH(request, noParams)

    expect(response.status).toBe(422)
    expect(usersService.updateCurrentUser).not.toHaveBeenCalled()
  })
})

describe("requireRole / assertOwnership", () => {
  it("returns 403 FORBIDDEN when the user lacks the role", async () => {
    signedIn("user_123")
    const adminOnly = createApiHandler(async () => {
      const { user } = await requireAuth()
      requireRole(user, "ADMIN")
      return { data: { ok: true } }
    })

    const response = await adminOnly(makeRequest("/api/admin"), noParams)
    expect(response.status).toBe(403)
    expect(await readBody(response)).toMatchObject({ error: { code: "FORBIDDEN" } })
  })

  it("allows users with the role", () => {
    expect(() => requireRole(makeUser({ role: "ADMIN" }), "ADMIN")).not.toThrow()
  })

  it("hides other users' resources as NOT_FOUND", () => {
    const user = makeUser()
    expect(() => assertOwnership(user, { userId: "someone-else" })).toThrow(expect.objectContaining({ code: "NOT_FOUND" }))
    expect(() => assertOwnership(user, null)).toThrow(expect.objectContaining({ code: "NOT_FOUND" }))
    expect(() => assertOwnership(user, { userId: user.id })).not.toThrow()
  })
})

import { afterEach, describe, expect, it, vi } from "vitest"

import { apiClient, ApiClientError } from "@/lib/api/api-client"
import { shouldRetryQuery } from "@/lib/api/query-client"

function mockFetch(impl: () => Promise<Response>) {
  vi.stubGlobal("fetch", vi.fn(impl))
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json", "x-request-id": "req_header123456" },
  })
}

async function capture(promise: Promise<unknown>): Promise<ApiClientError> {
  try {
    await promise
  } catch (error) {
    if (error instanceof ApiClientError) return error
    throw error
  }
  throw new Error("expected rejection")
}

afterEach(() => {
  vi.unstubAllGlobals()
})

describe("apiClient", () => {
  it("unwraps data from the success envelope and sends JSON", async () => {
    mockFetch(async () => json({ success: true, data: { id: 1 }, meta: { requestId: "req_abc12345" } }))

    await expect(apiClient.patch("/api/me", { baseCurrency: "EUR" })).resolves.toEqual({ id: 1 })

    const [, init] = vi.mocked(fetch).mock.calls[0]
    expect(new Headers(init?.headers).get("content-type")).toBe("application/json")
    expect(init?.body).toBe('{"baseCurrency":"EUR"}')
  })

  it("throws a typed http error with code, status, request ID and details", async () => {
    mockFetch(async () =>
      json(
        {
          success: false,
          error: { code: "VALIDATION_ERROR", message: "Please correct the highlighted fields.", details: { email: ["Bad"] } },
          meta: { requestId: "req_err12345" },
        },
        422
      )
    )

    const error = await capture(apiClient.post("/api/x", {}))
    expect(error).toMatchObject({
      kind: "http",
      status: 422,
      code: "VALIDATION_ERROR",
      requestId: "req_err12345",
      details: { email: ["Bad"] },
      message: "Please correct the highlighted fields.",
    })
  })

  it("distinguishes network failures", async () => {
    mockFetch(async () => {
      throw new TypeError("Failed to fetch")
    })
    const error = await capture(apiClient.get("/api/x"))
    expect(error.kind).toBe("network")
    expect(error.status).toBeNull()
  })

  it("distinguishes malformed JSON on success responses", async () => {
    mockFetch(async () => new Response("<html>oops</html>", { status: 200 }))
    const error = await capture(apiClient.get("/api/x"))
    expect(error.kind).toBe("parse")
  })

  it("distinguishes unexpected response shapes", async () => {
    mockFetch(async () => json({ hello: "world" }))
    const error = await capture(apiClient.get("/api/x"))
    expect(error).toMatchObject({ kind: "invalid_response", requestId: "req_header123456" })
  })

  it("treats a non-JSON 5xx (e.g. proxy error page) as an http error", async () => {
    mockFetch(async () => new Response("Bad Gateway", { status: 502 }))
    const error = await capture(apiClient.get("/api/x"))
    expect(error).toMatchObject({ kind: "http", status: 502, code: "UPSTREAM_ERROR" })
    expect(error.message).not.toContain("Bad Gateway")
  })

  it("reports cancellation as aborted", async () => {
    const controller = new AbortController()
    controller.abort()
    mockFetch(async () => {
      throw new DOMException("aborted", "AbortError")
    })
    const error = await capture(apiClient.get("/api/x", { signal: controller.signal }))
    expect(error.kind).toBe("aborted")
  })
})

describe("shouldRetryQuery", () => {
  const httpError = (status: number, code: ApiClientError["code"]) =>
    new ApiClientError({ kind: "http", message: "x", status, code })

  it.each([
    [400, "BAD_REQUEST"],
    [401, "UNAUTHORIZED"],
    [403, "FORBIDDEN"],
    [404, "NOT_FOUND"],
    [409, "CONFLICT"],
    [422, "VALIDATION_ERROR"],
  ] as const)("does not retry %i %s", (status, code) => {
    expect(shouldRetryQuery(0, httpError(status, code))).toBe(false)
  })

  it.each([
    [429, "RATE_LIMITED"],
    [500, "INTERNAL_ERROR"],
    [502, "UPSTREAM_ERROR"],
    [503, "SERVICE_UNAVAILABLE"],
  ] as const)("retries %i %s", (status, code) => {
    expect(shouldRetryQuery(0, httpError(status, code))).toBe(true)
  })

  it("retries network errors but stops at the retry limit", () => {
    const error = new ApiClientError({ kind: "network", message: "x" })
    expect(shouldRetryQuery(0, error)).toBe(true)
    expect(shouldRetryQuery(2, error)).toBe(false)
  })

  it("never retries malformed responses, cancellations, or unknown errors", () => {
    expect(shouldRetryQuery(0, new ApiClientError({ kind: "parse", message: "x" }))).toBe(false)
    expect(shouldRetryQuery(0, new ApiClientError({ kind: "invalid_response", message: "x" }))).toBe(false)
    expect(shouldRetryQuery(0, new ApiClientError({ kind: "aborted", message: "x" }))).toBe(false)
    expect(shouldRetryQuery(0, new Error("x"))).toBe(false)
  })
})

