/**
 * Shared agent types. Zod schemas are the single source of truth; TS types
 * are inferred from them. Agent-specific schemas live in agents/<name>/schema.ts.
 */
import { z } from "zod"

/** Tools that consume a per-run call budget (see lib/clients/callTool.ts). */
export type BudgetedTool = "crustdata" | "serp" | "firecrawl"

/** Remaining calls per tool for the current run. */
export type ToolBudget = Partial<Record<BudgetedTool, number>>

export const runVersionSchema = z.enum(["v1", "v2"])
/** v1 = intentionally naive baseline ("before"); v2 = the fix ("after"). */
export type RunVersion = z.infer<typeof runVersionSchema>

/** Tags attached to every trace span of a run. */
export type RunTags = {
  version: RunVersion
  country: string
  instrument: string
}

export type AgentContext = {
  runId: string
  /** Behaviour switch for every agent. Always equal to `trace.version`. */
  version: RunVersion
  budget: ToolBudget
  trace: RunTags
}

export const countrySchema = z.enum(["IN", "US", "OTHER"])
export type Country = z.infer<typeof countrySchema>

export const entityStatusSchema = z.enum(["unlisted", "ipo_filed", "listed"])
export type EntityStatus = z.infer<typeof entityStatusSchema>

export const instrumentSchema = z.enum(["ipo", "unlisted", "listed", "mf", "etf"])
export type Instrument = z.infer<typeof instrumentSchema>

/** Outcome of an agent. Agents never throw; failures are reported here. */
export const agentStatusSchema = z.enum(["ok", "unverifiable", "failed"])
export type AgentStatus = z.infer<typeof agentStatusSchema>

export const sourceIdsSchema = z.array(z.string().min(1))

/** The resolved company. Produced by the resolver, consumed by every later agent. */
export const entitySchema = z.object({
  legalName: z.string().min(1),
  country: countrySchema,
  status: entityStatusSchema,
  domain: z.string().min(1).optional(),
  /** Exchange symbols, e.g. "NSE:JIOFIN", "NASDAQ:AAPL". */
  symbols: z.array(z.string().min(1)).default([]),
  /** SEC CIK, 10 digits. */
  cik: z.string().regex(/^\d{10}$/).optional(),
  filingUrl: z.url().optional(),
  sourceIds: sourceIdsSchema,
})
export type Entity = z.infer<typeof entitySchema>

/** A single factual statement. Every claim cites stored Source rows. */
export const claimSchema = z.object({
  id: z.string().min(1),
  /** Check that produced it ("resolver" for identity claims). */
  checkId: z.string().min(1),
  field: z.string().min(1),
  statement: z.string().min(1),
  value: z.union([z.number(), z.string(), z.boolean()]).nullable().optional(),
  unit: z.string().optional(),
  /** Reporting period the value refers to, e.g. "FY2024". */
  period: z.string().optional(),
  sourceIds: sourceIdsSchema,
})
export type Claim = z.infer<typeof claimSchema>

export const sourceKindSchema = z.enum(["PRIMARY", "REGULATOR", "COMPANY", "REFERENCE", "NEWS", "AI_OVERVIEW"])
export type SourceKind = z.infer<typeof sourceKindSchema>

/** A stored Source row as agents see it. */
export const sourceRefSchema = z.object({
  id: z.string().min(1),
  url: z.string().min(1),
  kind: sourceKindSchema,
  title: z.string().optional(),
  publisher: z.string().optional(),
  text: z.string(),
  contentHash: z.string().min(1),
  publishedAt: z.string().optional(),
})
export type SourceRef = z.infer<typeof sourceRefSchema>

export function createAgentContext(input: {
  runId: string
  version: RunVersion
  country?: string
  instrument?: string
  budget?: ToolBudget
}): AgentContext {
  return {
    runId: input.runId,
    version: input.version,
    budget: input.budget ?? {},
    trace: { version: input.version, country: input.country ?? "unknown", instrument: input.instrument ?? "unknown" },
  }
}

import "server-only"

import type { Source, SourceKind } from "@/generated/prisma/client"
import { getPrisma } from "@/lib/db/prisma"

export type { Source }

export type SourceInput = {
  runId: string
  url: string
  kind: SourceKind
  publisher?: string
  title?: string
  excerpt: string
  contentHash: string
  legalNameMatched: boolean
  publishedAt?: Date
}

export const sourcesRepository = {
  /** Idempotent per (runId, url): retried steps reuse the same row and id. */
  upsert(input: SourceInput): Promise<Source> {
    const data = {
      kind: input.kind,
      publisher: input.publisher ?? null,
      title: input.title ?? null,
      excerpt: input.excerpt,
      contentHash: input.contentHash,
      legalNameMatched: input.legalNameMatched,
      publishedAt: input.publishedAt ?? null,
    }
    return getPrisma().source.upsert({
      where: { runId_url: { runId: input.runId, url: input.url } },
      create: { runId: input.runId, url: input.url, ...data },
      update: data,
    })
  },

  findByIds(runId: string, ids: string[]): Promise<Source[]> {
    if (ids.length === 0) return Promise.resolve([])
    return getPrisma().source.findMany({ where: { runId, id: { in: ids } } })
  },

  listByRun(runId: string): Promise<Source[]> {
    return getPrisma().source.findMany({ where: { runId }, orderBy: { fetchedAt: "asc" } })
  },
}

/**
 * No-investment-advice guard. Outputs are evidence, never recommendations.
 * Scans free-text fields only: names, URLs, ids and verbatim source quotes are
 * skipped (a company called "Strong Ltd" or a quoted "strong growth" is data).
 */

const ADVICE_PATTERN =
  /\b(buy|buys|buying|sell|sells|selling|strong|strongly|guarantee|guaranteed|price[- ]targets?|target price|recommend\w*|outperform|underperform)\b/gi

const SKIPPED_KEYS = new Set([
  "id",
  "ids",
  "url",
  "domain",
  "legalName",
  "name",
  "title",
  "symbols",
  "cik",
  "filingUrl",
  "quote",
  "says",
  "sourceIds",
  "contentHash",
  "claimId",
  "checkId",
])

export function findAdviceTerms(text: string): string[] {
  return [...new Set((text.match(ADVICE_PATTERN) ?? []).map((term) => term.toLowerCase()))]
}

/** Returns "path: term" for every advice term found in free-text fields of `value`. */
export function scanForAdvice(value: unknown, path = ""): string[] {
  if (typeof value === "string") {
    return findAdviceTerms(value).map((term) => `${path || "(root)"}: ${term}`)
  }
  if (Array.isArray(value)) {
    return value.flatMap((item, index) => scanForAdvice(item, `${path}[${index}]`))
  }
  if (value && typeof value === "object") {
    return Object.entries(value).flatMap(([key, item]) =>
      SKIPPED_KEYS.has(key) ? [] : scanForAdvice(item, path ? `${path}.${key}` : key)
    )
  }
  return []
}

import "server-only"

import type { z } from "zod"

import type { AgentContext, AgentStatus } from "@/agents/types"
import { scanForAdvice } from "@/agents/shared/advice"
import { span, type SetSpanAttributes } from "@/lib/clients/trace"

export type AgentName = "resolver" | "router" | "planner" | "extractor" | "verifier" | "reporter"

type FailStatus = Exclude<AgentStatus, "ok">

type RunAgentOptions<I extends z.ZodType, O extends z.ZodType> = {
  name: AgentName
  promptVersion: string
  ctx: AgentContext
  input: unknown
  inputSchema: I
  outputSchema: O
  /** Builds a valid output for a failure. Must not depend on parsed input. */
  fail: (status: FailStatus, reason: string) => z.input<O>
  body: (input: z.infer<I>, setAttributes: SetSpanAttributes) => Promise<z.input<O>>
}

function collectSourceIds(value: unknown, into: Set<string>): Set<string> {
  if (Array.isArray(value)) value.forEach((item) => collectSourceIds(item, into))
  else if (value && typeof value === "object") {
    for (const [key, item] of Object.entries(value)) {
      if (key === "sourceIds" && Array.isArray(item)) item.forEach((id) => typeof id === "string" && into.add(id))
      else collectSourceIds(item, into)
    }
  }
  return into
}

function countClaims(value: unknown): number {
  const claims = (value as { claims?: unknown })?.claims
  return Array.isArray(claims) ? claims.length : 0
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * Standard agent envelope:
 *   span → validate input → body → validate output → advice scan → counts.
 * Never throws: any failure becomes a schema-valid output with status
 * "failed" (or "unverifiable" when the body reports it) and a short reason.
 */
export async function runAgent<I extends z.ZodType, O extends z.ZodType>(
  opts: RunAgentOptions<I, O>
): Promise<z.infer<O>> {
  const { name, promptVersion, ctx, outputSchema } = opts
  const failed = (status: FailStatus, reason: string): z.infer<O> =>
    outputSchema.parse(opts.fail(status, reason.slice(0, 300)))

  try {
    return await span(
      `agent.${name}`,
      async (setAttributes) => {
        const parsedInput = opts.inputSchema.safeParse(opts.input)
        if (!parsedInput.success) {
          const paths = parsedInput.error.issues.map((issue) => issue.path.join(".") || "(root)")
          setAttributes({ "agent.error": "invalid input", "agent.status": "failed" })
          return failed("failed", `invalid input: ${[...new Set(paths)].join(", ")}`)
        }

        let output: z.infer<O>
        try {
          output = outputSchema.parse(await opts.body(parsedInput.data, setAttributes))
        } catch (error) {
          setAttributes({ "agent.error": errorMessage(error).slice(0, 500), "agent.status": "failed" })
          return failed("failed", `${name} failed: ${errorMessage(error)}`)
        }

        const advice = scanForAdvice(output)
        if (advice.length > 0) {
          setAttributes({ "agent.error": `advice language: ${advice.slice(0, 5).join("; ")}`, "agent.status": "failed" })
          return failed("failed", "output contained investment-advice language and was withheld")
        }

        setAttributes({
          "agent.status": String((output as { status?: unknown }).status ?? "ok"),
          "agent.claims": countClaims(output),
          "agent.sources": collectSourceIds(output, new Set()).size,
        })
        return output
      },
      {
        "agent.name": name,
        "agent.prompt_version": promptVersion,
        "research.version": ctx.version,
        "research.run_id": ctx.runId,
      },
      "AGENT"
    )
  } catch (error) {
    // Tracing itself failed; still honour the never-throw contract.
    return failed("failed", `${name} failed: ${errorMessage(error)}`)
  }
}

import "server-only"

import { z } from "zod"

import type { AgentContext } from "@/agents/types"
import type { AgentName } from "@/agents/shared/run-agent"
import { callTool } from "@/lib/clients/callTool"
import { complete, extract } from "@/lib/clients/llm"
import { span } from "@/lib/clients/trace"

type LlmCallMeta = {
  agent: AgentName
  promptVersion: string
  /** Short purpose label used in span names and cache keys, e.g. "candidates". */
  label: string
  system: string
  maxTokens?: number
}

/**
 * Structured LLM call: span → callTool("llm") → llm.extract → re-validate.
 * Returns null when the model call fails or the output does not match `schema`.
 */
export async function llmExtract<S extends z.ZodType>(
  ctx: AgentContext,
  meta: LlmCallMeta & { text: string; schema: S }
): Promise<z.infer<S> | null> {
  return span(
    `llm.${meta.agent}.${meta.label}`,
    async (setAttributes) => {
      const result = await callTool(
        ctx,
        "llm",
        {
          op: "extract",
          agent: meta.agent,
          promptVersion: meta.promptVersion,
          label: meta.label,
          system: meta.system,
          text: meta.text,
          schema: z.toJSONSchema(meta.schema),
        },
        (signal) => extract(meta.text, meta.schema, { system: meta.system, maxTokens: meta.maxTokens, signal })
      )
      // Cached values come back from JSON storage; validate again.
      const parsed = result === null ? null : meta.schema.safeParse(result)
      setAttributes({ "llm.ok": Boolean(parsed?.success) })
      return parsed?.success ? parsed.data : null
    },
    { "agent.name": meta.agent, "agent.prompt_version": meta.promptVersion, "research.version": ctx.version },
    "LLM"
  )
}

/** Free-text LLM call with the same tracing and caching. Returns null on failure. */
export async function llmComplete(
  ctx: AgentContext,
  meta: LlmCallMeta & { prompt: string; maxTokens: number }
): Promise<string | null> {
  return span(
    `llm.${meta.agent}.${meta.label}`,
    async () =>
      callTool(
        ctx,
        "llm",
        { op: "complete", agent: meta.agent, promptVersion: meta.promptVersion, label: meta.label, system: meta.system, prompt: meta.prompt },
        (signal) => complete({ system: meta.system, prompt: meta.prompt, maxTokens: meta.maxTokens, signal })
      ),
    { "agent.name": meta.agent, "agent.prompt_version": meta.promptVersion, "research.version": ctx.version },
    "LLM"
  )
}

import "server-only"

import { createHash } from "node:crypto"

import type { AgentContext, SourceKind, SourceRef } from "@/agents/types"
import { sourcesRepository, type Source } from "@/repositories/sources.repository"

/** Stored excerpts are capped; agents never keep a whole filing. */
export const MAX_EXCERPT_CHARS = 20_000

const REGULATOR_HOSTS = [
  "sec.gov",
  "sebi.gov.in",
  "nseindia.com",
  "bseindia.com",
  "mca.gov.in",
  "rbi.org.in",
]

export function hostOf(url: string): string | undefined {
  try {
    return new URL(url).hostname.toLowerCase().replace(/^www\./, "")
  } catch {
    return undefined
  }
}

export function normalizeDomain(value: string | undefined | null): string | undefined {
  if (!value) return undefined
  const trimmed = value.trim().toLowerCase()
  const host = hostOf(trimmed.includes("://") ? trimmed : `https://${trimmed}`)
  return host || undefined
}

function hostMatches(host: string | undefined, domain: string): boolean {
  return Boolean(host && (host === domain || host.endsWith(`.${domain}`)))
}

/** Classifies a web URL. Filings and AI overviews are labelled by the caller. */
export function classifyUrl(url: string, entityDomain?: string): SourceKind {
  const host = hostOf(url)
  if (REGULATOR_HOSTS.some((domain) => hostMatches(host, domain))) return "REGULATOR"
  const own = normalizeDomain(entityDomain)
  if (own && hostMatches(host, own)) return "COMPANY"
  return "NEWS"
}

export function normalizeText(text: string): string {
  return text.toLowerCase().replace(/\s+/g, " ").trim()
}

export function contentHash(text: string): string {
  return createHash("sha256").update(normalizeText(text)).digest("hex")
}

export function toSourceRef(row: Source): SourceRef {
  return {
    id: row.id,
    url: row.url,
    kind: row.kind,
    title: row.title ?? undefined,
    publisher: row.publisher ?? undefined,
    text: row.excerpt,
    contentHash: row.contentHash,
    publishedAt: row.publishedAt?.toISOString(),
  }
}

/** Persists a source for this run (idempotent per URL) and returns it as a SourceRef. */
export async function recordSource(
  ctx: AgentContext,
  input: {
    url: string
    kind: SourceKind
    text: string
    title?: string
    publisher?: string
    publishedAt?: Date
    legalNameMatched?: boolean
  }
): Promise<SourceRef> {
  const excerpt = input.text.slice(0, MAX_EXCERPT_CHARS)
  const row = await sourcesRepository.upsert({
    runId: ctx.runId,
    url: input.url,
    kind: input.kind,
    title: input.title,
    publisher: input.publisher,
    excerpt,
    contentHash: contentHash(excerpt),
    legalNameMatched: input.legalNameMatched ?? false,
    publishedAt: input.publishedAt,
  })
  return toSourceRef(row)
}

export async function loadSources(ctx: AgentContext, ids: string[]): Promise<SourceRef[]> {
  return (await sourcesRepository.findByIds(ctx.runId, [...new Set(ids)])).map(toSourceRef)
}

/** Company-name helpers shared by resolver and verifier. */

const SUFFIXES =
  /\b(inc|incorporated|corp|corporation|co|company|ltd|limited|pvt|private|plc|llc|llp|holdings?|group|the)\b/g

/** "Jio Platforms Limited" -> "jio platforms" */
export function normalizeLegalName(name: string): string {
  return name
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(SUFFIXES, " ")
    .replace(/\s+/g, " ")
    .trim()
}

export function sameCompanyName(a: string, b: string): boolean {
  const left = normalizeLegalName(a)
  return left.length > 0 && left === normalizeLegalName(b)
}

/** True when `text` names the company (normalized legal name) or its domain. */
export function textNamesEntity(text: string, entity: { legalName: string; domain?: string }): boolean {
  const haystack = ` ${normalizeLegalName(text)} `
  const name = normalizeLegalName(entity.legalName)
  if (name && haystack.includes(` ${name} `)) return true
  return Boolean(entity.domain && text.toLowerCase().includes(entity.domain.toLowerCase()))
}

/**
 * Deterministic financial arithmetic. The LLM never writes these numbers
 * (v2): it extracts inputs, and every computed value carries the union of
 * its inputs' sourceIds.
 */

/** An extracted input value with its evidence. */
export type SourcedNumber = { value: number; sourceIds: string[]; claimId: string }
export type SourcedString = { value: string; sourceIds: string[]; claimId: string }

export type ComputedMetric =
  | "market_cap_at_low"
  | "market_cap_at_high"
  | "pe_at_high"
  | "ps_at_high"
  | "ofs_percent"
  | "lock_in_end_date"
  | "revenue_growth_pct"
  | "implied_valuation_from_quote"
  | "headcount_change_pct"

export type ComputedValue = {
  metric: ComputedMetric
  value: number | string
  unit: "currency" | "ratio" | "percent" | "date"
  formula: string
  /** Claim ids of the inputs. */
  inputClaimIds: string[]
  sourceIds: string[]
}

/** Inputs available to compute, keyed by extracted field name. */
export type ComputeInputs = Partial<{
  priceLow: SourcedNumber
  priceHigh: SourcedNumber
  sharesOutstandingPostIssue: SourcedNumber
  revenueLatest: SourcedNumber
  revenuePrior: SourcedNumber
  netIncomeLatest: SourcedNumber
  freshIssueAmount: SourcedNumber
  ofsAmount: SourcedNumber
  listingDate: SourcedString
  lockInDays: SourcedNumber
  quotedPricePerShare: SourcedNumber
  headcountLatest: SourcedNumber
  headcountYearAgo: SourcedNumber
}>

function union(...inputs: Array<{ sourceIds: string[] }>): string[] {
  return [...new Set(inputs.flatMap((input) => input.sourceIds))]
}

function claims(...inputs: Array<{ claimId: string }>): string[] {
  return inputs.map((input) => input.claimId)
}

function round(value: number, digits: number): number {
  const factor = 10 ** digits
  return Math.round(value * factor) / factor
}

export function marketCap(price: SourcedNumber, shares: SourcedNumber): number {
  return price.value * shares.value
}

export function percentChange(latest: number, prior: number): number | undefined {
  return prior === 0 ? undefined : ((latest - prior) / Math.abs(prior)) * 100
}

/** Adds `days` to an ISO date (YYYY-MM-DD). Returns undefined for invalid dates. */
export function addDays(isoDate: string, days: number): string | undefined {
  const date = new Date(`${isoDate.slice(0, 10)}T00:00:00Z`)
  if (Number.isNaN(date.getTime())) return undefined
  date.setUTCDate(date.getUTCDate() + days)
  return date.toISOString().slice(0, 10)
}

/** Computes every metric whose inputs are present. Pure and deterministic. */
export function computeMetrics(inputs: ComputeInputs): ComputedValue[] {
  const out: ComputedValue[] = []
  const { priceLow, priceHigh, sharesOutstandingPostIssue: shares } = inputs

  if (priceLow && shares) {
    out.push({
      metric: "market_cap_at_low",
      value: marketCap(priceLow, shares),
      unit: "currency",
      formula: "priceLow × sharesOutstandingPostIssue",
      inputClaimIds: claims(priceLow, shares),
      sourceIds: union(priceLow, shares),
    })
  }

  if (priceHigh && shares) {
    const capHigh = marketCap(priceHigh, shares)
    out.push({
      metric: "market_cap_at_high",
      value: capHigh,
      unit: "currency",
      formula: "priceHigh × sharesOutstandingPostIssue",
      inputClaimIds: claims(priceHigh, shares),
      sourceIds: union(priceHigh, shares),
    })

    const income = inputs.netIncomeLatest
    if (income && income.value > 0) {
      out.push({
        metric: "pe_at_high",
        value: round(capHigh / income.value, 2),
        unit: "ratio",
        formula: "(priceHigh × shares) ÷ netIncomeLatest",
        inputClaimIds: claims(priceHigh, shares, income),
        sourceIds: union(priceHigh, shares, income),
      })
    }

    const revenue = inputs.revenueLatest
    if (revenue && revenue.value > 0) {
      out.push({
        metric: "ps_at_high",
        value: round(capHigh / revenue.value, 2),
        unit: "ratio",
        formula: "(priceHigh × shares) ÷ revenueLatest",
        inputClaimIds: claims(priceHigh, shares, revenue),
        sourceIds: union(priceHigh, shares, revenue),
      })
    }
  }

  const { freshIssueAmount: fresh, ofsAmount: ofs } = inputs
  if (fresh && ofs && fresh.value + ofs.value > 0) {
    out.push({
      metric: "ofs_percent",
      value: round((ofs.value / (fresh.value + ofs.value)) * 100, 1),
      unit: "percent",
      formula: "ofsAmount ÷ (freshIssueAmount + ofsAmount) × 100",
      inputClaimIds: claims(fresh, ofs),
      sourceIds: union(fresh, ofs),
    })
  }

  const { listingDate, lockInDays } = inputs
  if (listingDate && lockInDays) {
    const end = addDays(listingDate.value, lockInDays.value)
    if (end) {
      out.push({
        metric: "lock_in_end_date",
        value: end,
        unit: "date",
        formula: "listingDate + lockInDays",
        inputClaimIds: claims(listingDate, lockInDays),
        sourceIds: union(listingDate, lockInDays),
      })
    }
  }

  const { revenueLatest, revenuePrior } = inputs
  if (revenueLatest && revenuePrior) {
    const growth = percentChange(revenueLatest.value, revenuePrior.value)
    if (growth !== undefined) {
      out.push({
        metric: "revenue_growth_pct",
        value: round(growth, 1),
        unit: "percent",
        formula: "(revenueLatest − revenuePrior) ÷ |revenuePrior| × 100",
        inputClaimIds: claims(revenueLatest, revenuePrior),
        sourceIds: union(revenueLatest, revenuePrior),
      })
    }
  }

  const quote = inputs.quotedPricePerShare
  if (quote && shares) {
    out.push({
      metric: "implied_valuation_from_quote",
      value: marketCap(quote, shares),
      unit: "currency",
      formula: "quotedPricePerShare × sharesOutstandingPostIssue",
      inputClaimIds: claims(quote, shares),
      sourceIds: union(quote, shares),
    })
  }

  const { headcountLatest, headcountYearAgo } = inputs
  if (headcountLatest && headcountYearAgo) {
    const change = percentChange(headcountLatest.value, headcountYearAgo.value)
    if (change !== undefined) {
      out.push({
        metric: "headcount_change_pct",
        value: round(change, 1),
        unit: "percent",
        formula: "(headcountLatest − headcountYearAgo) ÷ headcountYearAgo × 100",
        inputClaimIds: claims(headcountLatest, headcountYearAgo),
        sourceIds: union(headcountLatest, headcountYearAgo),
      })
    }
  }

  return out
}

