/**
 * Shared mock factories for agent tests. Use inside vi.mock factories:
 *
 *   vi.mock("@/lib/clients/trace", async () => (await import("@/tests/support/agent-mocks")).traceMock())
 */
import { createAgentContext, type AgentContext, type SourceKind } from "@/agents/types"

/** span() runs fn directly and records names/attributes for assertions. */
export function traceMock() {
  const spans: Array<{ name: string; attrs: Record<string, unknown> }> = []
  return {
    __spans: spans,
    initTracing: async () => undefined,
    flush: async () => true,
    runTagAttributes: () => ({}),
    span: async (name: string, fn: (set: (a: Record<string, unknown>) => void) => Promise<unknown>, attrs?: Record<string, unknown>) => {
      const record = { name, attrs: { ...(attrs ?? {}) } }
      spans.push(record)
      return fn((more) => Object.assign(record.attrs, more))
    },
  }
}

/** callTool() without cache/DB: runs fn once; returns null on failure (same contract). */
export function callToolMock() {
  return {
    DEFAULT_TOOL_BUDGETS: { crustdata: 20, serp: 10, firecrawl: 15 },
    callTool: async (_run: unknown, _tool: string, _args: unknown, fn: (signal: AbortSignal) => Promise<unknown>) => {
      try {
        return await fn(new AbortController().signal)
      } catch {
        return null
      }
    },
  }
}

type StoredSource = {
  id: string
  runId: string
  url: string
  kind: SourceKind
  publisher: string | null
  title: string | null
  excerpt: string
  contentHash: string
  legalNameMatched: boolean
  publishedAt: Date | null
  fetchedAt: Date
}

/** In-memory Source table with the repository's (runId, url) idempotency. */
export function sourcesRepositoryMock() {
  const rows = new Map<string, StoredSource>()
  let seq = 0
  return {
    __rows: rows,
    sourcesRepository: {
      upsert: async (input: Omit<StoredSource, "id" | "fetchedAt" | "publisher" | "title" | "publishedAt"> & {
        publisher?: string
        title?: string
        publishedAt?: Date
      }) => {
        const key = `${input.runId}|${input.url}`
        const existing = rows.get(key)
        const row: StoredSource = {
          id: existing?.id ?? `src_${++seq}`,
          runId: input.runId,
          url: input.url,
          kind: input.kind,
          publisher: input.publisher ?? null,
          title: input.title ?? null,
          excerpt: input.excerpt,
          contentHash: input.contentHash,
          legalNameMatched: input.legalNameMatched,
          publishedAt: input.publishedAt ?? null,
          fetchedAt: existing?.fetchedAt ?? new Date(),
        }
        rows.set(key, row)
        return row
      },
      findByIds: async (runId: string, ids: string[]) =>
        [...rows.values()].filter((row) => row.runId === runId && ids.includes(row.id)),
      listByRun: async (runId: string) => [...rows.values()].filter((row) => row.runId === runId),
    },
  }
}

export function testContext(version: "v1" | "v2" = "v2"): AgentContext {
  return createAgentContext({ runId: "run_test", version })
}

import { describe, expect, it } from "vitest"

import { addDays, computeMetrics } from "@/compute"

const n = (value: number, claimId: string, sourceIds = [`s_${claimId}`]) => ({ value, claimId, sourceIds })

describe("computeMetrics", () => {
  it("computes market cap, P/E and P/S from extracted inputs with merged sourceIds", () => {
    const out = computeMetrics({
      priceLow: n(95, "price_low"),
      priceHigh: n(100, "price_high"),
      sharesOutstandingPostIssue: n(1_000_000, "shares"),
      netIncomeLatest: n(5_000_000, "income"),
      revenueLatest: n(20_000_000, "revenue"),
    })
    const byMetric = Object.fromEntries(out.map((v) => [v.metric, v]))

    expect(byMetric.market_cap_at_low.value).toBe(95_000_000)
    expect(byMetric.market_cap_at_high.value).toBe(100_000_000)
    expect(byMetric.pe_at_high.value).toBe(20)
    expect(byMetric.ps_at_high.value).toBe(5)
    expect(byMetric.pe_at_high.sourceIds.sort()).toEqual(["s_income", "s_price_high", "s_shares"])
    expect(byMetric.pe_at_high.inputClaimIds).toEqual(["price_high", "shares", "income"])
  })

  it("skips P/E for loss-making companies", () => {
    const out = computeMetrics({
      priceHigh: n(10, "p"),
      sharesOutstandingPostIssue: n(10, "s"),
      netIncomeLatest: n(-5, "i"),
    })
    expect(out.map((v) => v.metric)).toEqual(["market_cap_at_high"])
  })

  it("computes OFS %, revenue growth and lock-in end", () => {
    const out = computeMetrics({
      freshIssueAmount: n(300, "fresh"),
      ofsAmount: n(700, "ofs"),
      revenueLatest: n(120, "r1"),
      revenuePrior: n(100, "r0"),
      listingDate: { value: "2026-01-10", claimId: "listing", sourceIds: ["s_l"] },
      lockInDays: n(180, "lock"),
    })
    const byMetric = Object.fromEntries(out.map((v) => [v.metric, v.value]))
    expect(byMetric.ofs_percent).toBe(70)
    expect(byMetric.revenue_growth_pct).toBe(20)
    expect(byMetric.lock_in_end_date).toBe("2026-07-09")
  })

  it("returns nothing when inputs are missing", () => {
    expect(computeMetrics({ priceHigh: n(1, "p") })).toEqual([])
    expect(addDays("not a date", 3)).toBeUndefined()
  })
})

